import { describe, expect, it } from 'vitest';
import type { InputSnapshot } from '../input';
import type { Vec3 } from '../contracts/math';
import { CameraController, type CameraView } from './CameraController';

class FakeCamera implements CameraView {
  position={x:0,y:2,z:5,set:(x:number,y:number,z:number):void=>{this.position.x=x;this.position.y=y;this.position.z=z}};
  lookedAt:Vec3={x:0,y:0,z:0};
  lookAt(x:number,y:number,z:number):void{this.lookedAt={x,y,z}}
}
const dist=(a:Vec3,b:Vec3)=>Math.hypot(a.x-b.x,a.y-b.y,a.z-b.z);

describe('CameraController modes',()=>{
  it('aims at the active ball and supports orbit plus zoom',()=>{
    const ball={x:1,y:0,z:-2},camera=new FakeCamera(),controller=new CameraController(camera,{target:()=>ball,transitionSeconds:0});
    const before=controller.snapshot();controller.update(0,{orbitX:80,zoom:120});const after=controller.snapshot();
    expect(after).toMatchObject({mode:'aim',target:{x:1,y:.35,z:-2}});expect(after.yaw).not.toBe(before.yaw);expect(after.distance).toBeGreaterThan(before.distance);
  });
  it('follows a moving ball and uses an independent overview target',()=>{
    const ball={x:0,y:0,z:0},camera=new FakeCamera(),controller=new CameraController(camera,{target:()=>ball,overviewTarget:{x:20,y:1,z:-10},transitionSeconds:0});
    controller.setMode('follow');ball.x=7;ball.z=-3;controller.update(1/60);expect(controller.snapshot()).toMatchObject({mode:'follow',target:{x:7,y:.45,z:-3}});
    controller.setMode('overview');const overview=controller.snapshot();expect(overview.target).toEqual({x:20,y:1.4,z:-10});expect(overview.position.y-overview.target.y).toBeGreaterThan(10);
  });
  it('moves free camera from WASD-style control state',()=>{
    const controller=new CameraController(new FakeCamera(),{target:{x:0,y:0,z:0},transitionSeconds:0});controller.setMode('free');const before=controller.snapshot();controller.update(1,{moveForward:true,moveRight:true,orbitX:20});const after=controller.snapshot();expect(after.mode).toBe('free');expect(after.position).not.toEqual(before.position);expect(after.target).not.toEqual(before.target);
  });
  it('interpolates mode changes until the transition completes',()=>{
    const controller=new CameraController(new FakeCamera(),{target:{x:0,y:0,z:0},transitionSeconds:0});controller.setMode('follow',{duration:.5});const start=controller.snapshot().position;controller.update(.25);expect(controller.snapshot().transitioning).toBe(true);expect(controller.snapshot().position).not.toEqual(start);controller.update(.25);expect(controller.isTransitioning).toBe(false);expect(controller.mode).toBe('follow');
  });
  it('uses the shared raycast contract to clear obstacles',()=>{
    const controller=new CameraController(new FakeCamera(),{target:{x:0,y:0,z:0},transitionSeconds:0,collision:{cast:()=>({distance:2})}});const s=controller.snapshot();expect(dist(s.position,s.target)).toBeCloseTo(1.82);
  });
  it('adapts the shared InputManager snapshot for free movement',()=>{
    const controller=new CameraController(new FakeCamera(),{target:{x:0,y:0,z:0},transitionSeconds:0});controller.setMode('free');const input:InputSnapshot={pointer:{x:0,y:0,deltaX:10,deltaY:0,wheel:0,primaryDown:true},isDown:a=>a==='camera-forward',wasPressed:()=>false,wasReleased:()=>false};const before=controller.snapshot().position;controller.updateFromInput(1,input);expect(controller.snapshot().position).not.toEqual(before);
  });
});
